-- ============================================================================
-- GROWTH BENCHMARKING & COMPARISONS
-- ============================================================================

CREATE TABLE IF NOT EXISTS growth_benchmarks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  age_in_days INT NOT NULL,
  gender TEXT NOT NULL CHECK (gender IN ('male', 'female')),
  metric TEXT NOT NULL CHECK (metric IN ('height', 'weight', 'head_circumference')),
  percentile_5 DECIMAL(6,2),
  percentile_25 DECIMAL(6,2),
  percentile_50 DECIMAL(6,2),
  percentile_75 DECIMAL(6,2),
  percentile_95 DECIMAL(6,2),
  unit TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS milestone_benchmarks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  age_in_months INT NOT NULL,
  milestone_category TEXT NOT NULL CHECK (milestone_category IN ('gross_motor', 'fine_motor', 'cognitive', 'social_emotional', 'language')),
  milestone_name TEXT NOT NULL,
  typical_age_min_months INT,
  typical_age_max_months INT,
  description TEXT,
  development_tips TEXT,
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS baby_benchmarks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  baby_id UUID NOT NULL REFERENCES babies(id) ON DELETE CASCADE,
  metric TEXT NOT NULL,
  value DECIMAL(6,2),
  percentile INT,
  comparison_vs_peers DECIMAL(5,1),
  recorded_date DATE,
  created_at TIMESTAMP DEFAULT NOW()
);

-- Create indexes
CREATE INDEX IF NOT EXISTS idx_growth_benchmarks_age_gender ON growth_benchmarks(age_in_days, gender);
CREATE INDEX IF NOT EXISTS idx_milestone_benchmarks_age ON milestone_benchmarks(age_in_months);
CREATE INDEX IF NOT EXISTS idx_baby_benchmarks_baby_id ON baby_benchmarks(baby_id);
